 async function actions(action){sync();const p=M.cfgInicial(DB.uf);switch(action){
  case'export-list':await exportList();break;case'export-tax-matrix':exportTaxMatrix();break;case'export-annexes':exportAnnexes();break;
  case'export-memory':exportMemory();break;case'export-memory-json':exportMemory(true);break;case'export-years':exportYears();break;
  case'export-budget-xlsx':await exportBudgetXLSX();break;case'export-budget-csv':exportBudgetCSV();break;case'print':printTax();break;case'legal':legal();break;
  case'save':save();toast('Gravação do projeto solicitada. A confirmação de falha, se houver, será exibida.');break;
  case'export-scenario':OP.exp.download('Cenario_IVA_OrcaPlan.json',JSON.stringify(scenario(),null,2),'application/json');break;
  case'import':{const f=await UI.pickFile('.json,application/json');if(!f)break;if(f.size>10000000)throw new Error('Cenário acima de 10 MB.');const z=JSON.parse((await f.text()).replace(/^\uFEFF/,'')),src=z.cfg||z.parametros||z.project?.iva?.cfg;if(!src)throw new Error('Use um cenário JSON do aplicativo anexo ou um projeto OrçaPlan.');const candidate=M.validarCfg(src,DB.uf,true);if(!confirm('Substituir o cenário tributário deste projeto? Os preços, a UF e o regime previdenciário do orçamento serão mantidos.'))break;const extra=z.orcaplan||z.project?.iva||{};A.pj.iva.cfg=candidate;A.pj.iva.priceMode=extra.priceMode==='budget'?'budget':'source';A.pj.iva.valuation=extra.valuation==='budget'?'budget':'reference';A.pj.iva.terminals=extra.terminals||{};const y=z.st?.ano||z.contexto?.ano||extra.year;if(M.ANOS.includes(+y))A.pj.iva.year=+y;T.invalidate();sync();refresh();toast('Cenário importado; UF, regime e preços do orçamento preservados.');break;}
  case'reset-all':if(confirm('Restaurar as premissas tributárias? O orçamento não será apagado.')){CFG=p;A.pj.iva.terminals={};changed();}break;
  case'reset-rates':CFG.ibs=p.ibs;CFG.cbs=p.cbs;changed();break;case'reset-iss':CFG.iss=p.iss;changed();break;
  case'reset-credits':CFG.par=p.par;CFG.fatorAliquota=p.fatorAliquota;CFG.operadorParametrico=false;changed();break;
  case'reset-annexes':CFG.regimeInsumo={...M.REGIME_PADRAO};changed();break;
  case'reset-item':{const d=selected();delete CFG.base.porInsumo[d.item.c];changed();break;}
  case'fuel-auto':CFG.combustiveis[ST.combustivel].anos=M.ANOS.map(()=>({ibs:null,cbs:null}));changed();break;
  case'reset-fuel':CFG.combustiveis[ST.combustivel]=p.combustiveis[ST.combustivel];changed();break;
  case'save-terminal':{const key=A.ivaTerminal,profile=$('#iva-terminal-profile').value,note=$('#iva-terminal-note').value;if(profile)A.pj.iva.terminals[key]={profile,note};else delete A.pj.iva.terminals[key];UI.closeModal();T.invalidate();refresh();toast('Perfil de cenário aplicado; item permanece sem analítico.');break;}
  case'tests':{toast('Executando verificações locais…');await new Promise(r=>setTimeout(r,20));let results=T.runTests();$('#iva-test-results').textContent=results.map(x=>(x.ok?'✓ ':'✗ ')+x.nome+(x.erro?' — '+x.erro:'')).join('\n')+'\n\n'+results.filter(x=>x.ok).length+'/'+results.length+' verificações aprovadas. Testes de software, não certificação fiscal.';M.configurarPrecos(CFG);break;}
 }}
